// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/healthz", wrapper.GetHealth)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/claims", wrapper.CreateClaim)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/claims/{claimId}", wrapper.GetClaim)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/claims/{claimId}/documents", wrapper.CreateDocumentUpload)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/claims/{claimId}/documents/{documentId}/complete", wrapper.CompleteDocumentUpload)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/claims/{claimId}/submit", wrapper.SubmitClaim)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/claims/{claimId}/events", wrapper.StreamClaimEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/claims/{claimId}/adjudication", wrapper.GetAdjudication)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/claims/{claimId}/audit", wrapper.ListAuditEvents)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/review-tasks", wrapper.ListReviewTasks)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/review-tasks/{taskId}/claim", wrapper.ClaimReviewTask)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/review-tasks/{taskId}/decision", wrapper.DecideReviewTask)

	return m
}

