// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetHealth Check that the process is up
	// (GET /healthz)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// CreateClaim Create a draft claim
	// (POST /v1/claims)
	CreateClaim(ctx context.Context, request CreateClaimRequestObject) (CreateClaimResponseObject, error)
	// GetClaim Get a claim's status, timeline and totals
	// (GET /v1/claims/{claimId})
	GetClaim(ctx context.Context, request GetClaimRequestObject) (GetClaimResponseObject, error)
	// GetAdjudication Get the line items, adjustments and clause references
	// (GET /v1/claims/{claimId}/adjudication)
	GetAdjudication(ctx context.Context, request GetAdjudicationRequestObject) (GetAdjudicationResponseObject, error)
	// ListAuditEvents Get a claim's audit trail
	// (GET /v1/claims/{claimId}/audit)
	ListAuditEvents(ctx context.Context, request ListAuditEventsRequestObject) (ListAuditEventsResponseObject, error)
	// CreateDocumentUpload Get a short-lived upload URL for one file
	// (POST /v1/claims/{claimId}/documents)
	CreateDocumentUpload(ctx context.Context, request CreateDocumentUploadRequestObject) (CreateDocumentUploadResponseObject, error)
	// CompleteDocumentUpload Confirm an upload so it can be checked
	// (POST /v1/claims/{claimId}/documents/{documentId}/complete)
	CompleteDocumentUpload(ctx context.Context, request CompleteDocumentUploadRequestObject) (CompleteDocumentUploadResponseObject, error)
	// StreamClaimEvents Follow a claim's status as server-sent events
	// (GET /v1/claims/{claimId}/events)
	StreamClaimEvents(ctx context.Context, request StreamClaimEventsRequestObject) (StreamClaimEventsResponseObject, error)
	// SubmitClaim Lock the documents and start adjudication
	// (POST /v1/claims/{claimId}/submit)
	SubmitClaim(ctx context.Context, request SubmitClaimRequestObject) (SubmitClaimResponseObject, error)
	// ListReviewTasks List the review queue
	// (GET /v1/review-tasks)
	ListReviewTasks(ctx context.Context, request ListReviewTasksRequestObject) (ListReviewTasksResponseObject, error)
	// ClaimReviewTask Take a review task under a time-limited lease
	// (POST /v1/review-tasks/{taskId}/claim)
	ClaimReviewTask(ctx context.Context, request ClaimReviewTaskRequestObject) (ClaimReviewTaskResponseObject, error)
	// DecideReviewTask Approve, correct or override, with reason codes
	// (POST /v1/review-tasks/{taskId}/decision)
	DecideReviewTask(ctx context.Context, request DecideReviewTaskRequestObject) (DecideReviewTaskResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

